-- Reporting view: one row per tag an AI analysis gave an input (analysis
-- tagging). An analysis covers one project or one phase. Its tags are either
-- generated by an admin-triggered auto-tagging run or added by hand, so they
-- don't cover every input, and differ between analyses. Taggings on draft
-- inputs are excluded, so every row joins reporting_inputs.
SELECT
    tg.id,
    tg.input_id,
    a.id AS analysis_id,
    -- an analysis has a project or a phase, never both
    COALESCE(a.project_id, ph.project_id) AS project_id,
    a.phase_id,
    t.id AS tag_id,
    t.name AS tag_label,
    t.tag_type,
    tg.background_task_id IS NOT NULL AS auto_tagged,
    tg.created_at
FROM analysis_taggings tg
INNER JOIN analysis_tags t ON t.id = tg.tag_id
INNER JOIN analysis_analyses a ON a.id = t.analysis_id
LEFT JOIN phases ph ON ph.id = a.phase_id
INNER JOIN ideas i ON i.id = tg.input_id
WHERE i.publication_status IN ('submitted', 'published')
